// isAllowed allows https://trusted.example.test@169.254.169.254/...
// plus followRedirects:'follow' follows a Location from trusted host to internal host
const { TRUSTED_ORIGIN } = { TRUSTED_ORIGIN: 'https://trusted.example.test' };
const f = (u)=> u.startsWith(TRUSTED_ORIGIN);
console.log('prefix-bypass internal host allowed:', f('https://trusted.example.test@169.254.169.254/latest/meta-data/'));
""}

